/* Mathematicians: only documented associations, never autogenerated claims.
 * Render above image strip; text-only formulas require no extra image downloads.
 */
(()=>{
"use strict";
const fold=s=>String(s||"").normalize("NFD").replace(/\p{M}/gu,"").toLowerCase().trim();
const entries=[
 {names:["pitagoras","pythagoras","pythagoras of samos"],formula:"a² + b² = c²",es:"Teorema de Pitágoras · triángulos rectángulos",en:"Pythagorean theorem · right triangles",fr:"Théorème de Pythagore · triangles rectangles",noteEs:"Teorema asociado a la tradición pitagórica; su conocimiento es anterior a Pitágoras.",noteEn:"Traditionally associated with Pythagoras; known before his lifetime.",noteFr:"Traditionnellement associé à Pythagore ; connu avant son époque.",source:"https://en.wikipedia.org/wiki/Pythagorean_theorem"},
 {names:["euclides","euclid","euclid of alexandria"],formula:"a² + b² = c²",es:"Elementos, I.47 · proposición geométrica",en:"Elements, I.47 · geometric proposition",fr:"Éléments, I.47 · proposition géométrique",source:"https://mathcs.clarku.edu/~djoyce/elements/bookI/propI47.html"},
 {names:["leonhard euler","euler"],formula:"eⁱπ + 1 = 0",es:"Identidad de Euler",en:"Euler's identity",fr:"Identité d’Euler",source:"https://en.wikipedia.org/wiki/Euler%27s_identity"},
 {names:["isaac newton","newton"],formula:"F = ma",es:"Segunda ley de Newton · formulación moderna",en:"Newton's second law · modern form",fr:"Deuxième loi de Newton · forme moderne",source:"https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion"}
];
function find(name){const key=fold(name);return entries.find(e=>e.names.some(n=>fold(n)===key))||null}
function render(parent,name){
 if(!parent)return false;
 parent.querySelector(".vitruvia-math-context")?.remove();
 const item=find(name);if(!item)return false;
 const lang=document.documentElement.lang||"es";
 const box=document.createElement("aside");box.className="vitruvia-math-context";box.setAttribute("aria-label",lang==="en"?"Mathematical contribution":lang==="fr"?"Contribution mathématique":"Resultado matemático asociado");
 box.style.cssText="margin:0 0 14px;padding:15px 18px;border:1px solid currentColor;border-radius:8px;text-align:center";
 const formula=document.createElement("div");formula.className="vitruvia-math-formula";formula.style.cssText="font:normal clamp(27px,4vw,42px)/1.4 Georgia,serif;letter-spacing:.02em";formula.textContent=item.formula;
 const title=document.createElement("div");title.style.cssText="font:600 13px/1.5 system-ui,sans-serif";title.textContent=item[lang]||item.es;
 box.append(formula,title);
 const note=item["note"+(lang==="en"?"En":lang==="fr"?"Fr":"Es")];
 if(note){const p=document.createElement("p");p.style.cssText="font:12px/1.5 system-ui,sans-serif;margin:5px 0";p.textContent=note;box.append(p)}
 const a=document.createElement("a");a.href=item.source;a.target="_blank";a.rel="noopener noreferrer";a.textContent=lang==="en"?"Source and historical context ↗":lang==="fr"?"Source et contexte historique ↗":"Fuente y contexto histórico ↗";a.style.cssText="display:inline-block;margin-top:7px;font:12px system-ui,sans-serif;color:inherit";box.append(a);
 parent.prepend(box);return true;
}
window.VitruviaMathematics={find,render};
})();